<?php
namespace App\Http\Controllers\HR;
use App\Http\Controllers\Controller; use App\Models\AttendanceStatus; use Illuminate\Http\Request; use Inertia\Inertia; use Inertia\Response;
class AttendanceConfigurationController extends Controller { public function index(): Response { return Inertia::render('HR/Attendance/Configuration/Index',['statuses'=>AttendanceStatus::orderBy('sort_order')->get()]); } public function storeStatus(Request $r){$d=$r->validate(['name'=>'required|string|max:100','code'=>'required|string|max:100|unique:attendance_statuses,code','description'=>'nullable|string','color'=>'nullable|string|max:30','is_working'=>'boolean','is_active'=>'boolean','sort_order'=>'integer']); AttendanceStatus::create(array_merge($d,['created_by'=>$r->user()->id])); return back()->with('success','Attendance status created.');} public function updateStatus(Request $r,AttendanceStatus $attendanceStatus){$d=$r->validate(['name'=>'required|string|max:100','description'=>'nullable|string','color'=>'nullable|string|max:30','is_working'=>'boolean','is_active'=>'boolean','sort_order'=>'integer']);$attendanceStatus->update(array_merge($d,['updated_by'=>$r->user()->id]));return back()->with('success','Attendance status updated.');} }
